import json, hashlib, html, base64, re
from pathlib import Path
R=Path(__file__).resolve().parent
def load(p): return json.loads((R/p).read_text())
def esc(v): return html.escape(str(v))
def paras(v): return ''.join('<p>'+esc(p).replace('\n','<br>')+'</p>' for p in v.split('\n\n'))
cases=load('rubric.json'); protocol=load('protocol.json'); key=load('blind-key.json')
outs={n:{x['id']:x['output'] for x in load('outputs/'+n+'.json')} for n in ['cedar-one','cedar-two','amber-one','amber-two']}
reviews={n:{x['pair_id']:x for x in load('judging/reviewer-'+n+'.json')} for n in ['one','two']}
frozen=load('frozen-input-hashes.json')
assert all(hashlib.sha256((R/f).read_bytes()).hexdigest()==h for f,h in frozen.items())
assert len(load('judging/deterministic-checks.json'))==72
assert all(not x['failures'] for x in load('judging/deterministic-checks.json'))
for rev in reviews.values():
 assert len(rev)==36
 assert all(x['preference']=='tie' and x['A']['rating']==x['B']['rating']=='pass' for x in rev.values())
same4=[c['id'] for c in cases if len({o[c['id']] for o in outs.values()})==1]
samepair=sum(outs['cedar-'+n][c['id']]==outs['amber-'+n][c['id']] for n in ['one','two'] for c in cases)
baseline={}
for root in ['/Volumes/BeastMode/40-skills/work/Skills-Estate/skills/writing-integrity','/Users/meganshellman/.agents/skills/writing-integrity','/Users/meganshellman/.claude/skills/writing-integrity']:
 baseline[root]=all(hashlib.sha256((Path(root)/f).read_bytes()).hexdigest()==h for f,h in protocol['baseline_source_hashes'].items())
assert all(baseline.values())
summary={'cases':18,'outputs':72,'outputs_per_condition':36,'reviews_per_output':2,'paired_comparisons_per_reviewer':36,'ties_per_reviewer':36,'mechanical_failures':0,'identical_across_all_four_runs':same4,'identical_current_candidate_pairs':samepair,'frozen_hashes_verified':True,'baseline_unchanged':baseline,'candidate_installed':False}
(R/'results.json').write_text(json.dumps(summary,indent=2)+'\n')
S=Path('/Users/meganshellman/.codex/skills/editorial-design')
css=(S/'assets/colors_and_type.css').read_text()
css=re.sub(r'@font-face\s*\{.*?\}',lambda m:m[0] if any('font-weight: '+str(w)+';' in m[0] for w in [400,600,700]) and 'font-style: normal' in m[0] else '',css,flags=re.S)
css=re.sub(r'url\("(fonts/[^\"]+)"\)',lambda m:'url("data:font/ttf;base64,'+base64.b64encode((S/'assets'/m[1]).read_bytes()).decode()+'")',css)
css+='''
*{box-sizing:border-box}body{margin:0}main{max-width:1120px;margin:auto;padding:64px 32px}h1{font-size:48px;max-width:850px;margin:16px 0 24px}h2{margin:48px 0 16px}h3{margin:24px 0 8px}p,li{font-size:16px;line-height:1.6}p{max-width:880px;color:var(--fg)}.lead{font-size:20px;max-width:880px}.meta{color:var(--fg-secondary);font-size:14px}.result{padding-bottom:32px;border-bottom:1px solid var(--border)}table{width:100%;border-collapse:collapse;margin:24px 0;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:16px 12px;border-bottom:1px solid var(--border);font-size:16px}th{background:var(--sand)}th:not(:first-child),td:not(:first-child){text-align:right}.note{background:var(--sand);padding:24px;margin:32px 0}.note h2{margin-top:0}.cols{display:grid;grid-template-columns:1fr 1fr;gap:32px}.cols>div{min-width:0}blockquote{margin:12px 0 24px;padding:0}blockquote p{font-size:16px}details{border-top:1px solid var(--border);padding:16px 0}summary{font-size:18px;font-weight:600;cursor:pointer;padding:8px 0}summary:focus-visible,a:focus-visible{outline:2px solid var(--focus-ring);outline-offset:4px}.task{background:var(--off-white);padding:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.5}.review{font-size:14px;color:var(--fg-secondary)}.sample p{white-space:pre-wrap;overflow-wrap:anywhere}nav{display:flex;gap:24px;flex-wrap:wrap;margin:24px 0 40px}footer{margin-top:48px;border-top:1px solid var(--border);padding-top:24px}li{margin:8px 0}.evidence{overflow-wrap:anywhere}.license{font-size:12px} @media(max-width:640px){main{padding:32px 20px}h1{font-size:36px}.cols{grid-template-columns:1fr;gap:8px}th,td{font-size:14px;padding:12px 8px}nav{gap:16px}.note{padding:16px}}
@media print{main{padding:0;max-width:none}nav{display:none}h1{font-size:32px}p,li,th,td{font-size:11px}details{break-inside:avoid}summary{font-size:14px}.cols{gap:20px}h2{break-after:avoid}.note{break-inside:avoid}details:not([open])>*:not(summary){display:none}footer{font-size:10px}}
'''
body='''<main><header class="result"><div class="eyebrow">Writing Integrity · behavioral comparison · 22 October 2026</div><h1>The proposed revision did not outperform the existing skill.</h1><p class="lead">Across 18 tasks and two runs per version, both blinded reviewers rated every response as passing and tied every comparison. This run provides no behavioral basis for replacing the existing skill with the proposed revision.</p><p class="meta">72 generated responses · 36 matched pairs · 2 blinded model reviewers</p></header><nav aria-label="Report sections"><a href="#findings">Findings</a><a href="#limits">What the test can establish</a><a href="#cases">Inspect the responses</a><a href="#revision">Proposed changes</a></nav>
<section id="findings"><h2>Both versions passed the checks used here</h2><table><thead><tr><th scope="col">Observed result</th><th scope="col">Existing</th><th scope="col">Proposed</th></tr></thead><tbody><tr><th scope="row">Responses generated</th><td>36</td><td>36</td></tr><tr><th scope="row">Responses with a mechanical constraint failure</th><td>0</td><td>0</td></tr><tr><th scope="row">Rated pass by reviewer one</th><td>36 / 36</td><td>36 / 36</td></tr><tr><th scope="row">Rated pass by reviewer two</th><td>36 / 36</td><td>36 / 36</td></tr><tr><th scope="row">Preferred by either reviewer</th><td>0</td><td>0</td></tr></tbody></table><p>Each reviewer recorded 36 ties. Seventeen of the 36 matched pairs were word-for-word identical. Eight tasks produced the same response in all four runs.</p><p>The cases covered preserving effective prose and voice, requested conclusions, summary selection, separate uncertainties, unpublished misconceptions, necessary correction notices, conversation continuity, local editing scope, useful contrasts, quotations, factual review and technical meaning. Neither reviewer tagged an overcorrection, missed correction, factual loss, scope violation or format violation.</p>
<div class="note"><h2>The pass ratings missed an editorial concern</h2><p>Every release-note response appended a statement that adoption or productivity had not been measured. That fact constrained what could be claimed; it did not need to become customer-facing copy about the new editor behavior.</p><div class="cols"><div><h3>Existing skill · first run</h3><blockquote>'''+paras(outs['cedar-one']['T12'])+'''</blockquote></div><div><h3>Proposed revision · first run</h3><blockquote>'''+paras(outs['amber-one']['T12'])+'''</blockquote></div></div><p>The reviewers accepted these because the caveat did not dominate the release note. My editorial assessment is that it is still unnecessary. This is a limitation of the grading criteria, which asked whether the disclaimer was central rather than whether it belonged. The recorded ratings remain unchanged.</p></div>
<h2>The original Meridian problem was not reproduced</h2><p>Both versions led with the consulting team’s scattered knowledge and the intended product purpose. Neither explained the AI’s private drafting mistake or described what the brief contained. However, the task explicitly supplied that framing and requested a short opening. Success under those conditions does not establish that either version will recover well during a longer, less directed revision.</p></section>
<section id="limits"><h2>Use this as a diagnostic, not proof of reliability</h2><p>The candidate and case criteria were fixed before generation. Four fresh writer agents each read one assigned skill version and all four substantive references, then answered the same 18 tasks. Two fresh reviewers received randomized A/B pairs, task instructions and criteria, without the condition names or the earlier discussion. The condition key was used to interpret the completed reviews.</p><p>These were real generated responses, not a simulation of what an agent might say. Word limits, required quotations and protected JSON fields were also checked mechanically where specified. Canonical and installed skill hashes still match the starting snapshot; the candidate has not been installed.</p><ul><li>Each writer answered 18 cases in one session. The cases were not isolated into 72 separate contexts.</li><li>Writers and reviewers shared the same model family and platform instructions. Those instructions may suppress failures even when a skill contains a risky rule.</li><li>Many task instructions directly specified the desired restraint. That makes compliance easier and may hide differences between the skills.</li><li>The same author prepared the candidate and rubric. Blinding reduces reviewer bias but does not make the test independent human evaluation.</li><li>Two runs per condition are too few to estimate failure rates. Longer documents, other models and day-to-day use remain untested.</li><li>No no-skill control was included. The results cannot establish that either skill caused the successful behavior.</li></ul><p><strong>Recommendation:</strong> keep the candidate staged. Its wording addresses plausible rule conflicts, but this comparison does not demonstrate an improvement. A further evaluation should use realistic longer artifacts with fewer coaching instructions and a relevance criterion that catches unnecessary internal caveats. No replacement or broader rollout is supported by these scores alone.</p></section>
<section id="cases"><h2>Inspect all 18 tasks and 72 responses</h2><p>Open a case to see its original task, criteria, both runs and the blinded reviewer explanations. Text is preserved verbatim. Existing means the source-matched installed skill; proposed means the staged revision.</p>
'''
for c in cases:
 body+=f'<details id="{c["id"]}"><summary>{esc(c["category"].capitalize())} <small>· {c["id"]}</small></summary><div class="task">{paras(c["task"])}</div><h3>Criteria fixed before generation</h3><ul>'+''.join('<li>'+esc(v)+'</li>' for v in c['criteria'])+'</ul>'
 for rep,num in [('one',1),('two',2)]:
  pid=next(p for p,v in key.items() if v['case_id']==c['id'] and v['replicate']==rep)
  body+=f'<h3>Run {num}</h3><div class="cols">'
  for condition,label in [('cedar','Existing'),('amber','Proposed')]:
   blind=next(x for x in ['A','B'] if key[pid][x]==condition)
   body+='<div class="sample"><h4>'+label+'</h4>'+paras(outs[condition+'-'+rep][c['id']])
   for rev,rnum in [('one',1),('two',2)]:
    reason=reviews[rev][pid][blind]
    body+=f'<p class="review">Reviewer {rnum}: {esc(reason["rating"])}. {esc(reason["reason"])}</p>'
   body+='</div>'
  body+='</div>'
 body+='</details>'
body+='''</section><section id="revision"><h2>The revision tested narrower editorial judgment</h2><p>The candidate replaces automatic prose rules with decisions tied to meaning, audience and the requested task. It permits useful summaries, general or emotional sentences, separate uncertainties and necessary correction notices. It also limits local corrections to affected content and distinguishes standalone artifacts from ongoing conversation.</p><p>The experiment changed SKILL.md and two references. Other references and metadata were preserved. The exact diff follows; the evidence archive contains both complete skill snapshots, tasks, criteria, protocol, raw responses, blinded reviews, the randomization key and hash records.</p><details><summary>Read the exact proposed revision</summary><pre>'''+esc((R/'candidate.diff').read_text())+'''</pre></details></section><footer><p class="meta evidence">Evidence files: protocol.json · rubric.json · outputs/*.json · judging/reviewer-one.json · judging/reviewer-two.json · judging/deterministic-checks.json · blind-key.json · results.json · frozen-input-hashes.json</p><p class="meta">The installed skill was unchanged during this evaluation.</p><details><summary>Embedded font license</summary><pre class="license">'''+esc((S/'assets/fonts/OFL.txt').read_text())+'</pre></details></footer></main>'
(R/'writing-integrity-comparison.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Writing Integrity — behavioral comparison</title><style>'+css+'</style></head><body>'+body+'</body></html>')
manifest={'manifestVersion':'1.0','artifactId':'writing-integrity-comparison','decisionJob':'Compare existing and proposed writing skill','requiredPhrases':['The proposed revision did not outperform the existing skill.','Seventeen of the 36 matched pairs were word-for-word identical.','The pass ratings missed an editorial concern','The candidate has not been installed.'],'forbiddenPhrases':[],'requiredEvidenceReferences':['protocol.json','results.json'],'protectedClaims':[],'requiredSelectors':['main','h1','#cases','#limits'],'requiredViews':['desktop','narrow','print']}
manifest['requiredPhrases'][-1]='the candidate has not been installed.'
(R/'parity-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps(summary,indent=2))
